218	/** Stable per-object identity, standing in for CPython's `id()`. */
219	export function objectId(o) {
220	  if (o === null || (typeof o !== 'object' && typeof o !== 'function')) return 'v' + String(o);
221	  let v = idMap.get(o);
222	  if (v === undefined) {
223	    v = ++idCounter;
224	    idMap.set(o, v);
