474	  for (let width = 1; width < n; width *= 2) {
475	    for (let lo = 0; lo < n; lo += 2 * width) {
476	      const mid = Math.min(lo + width, n);
477	      const hi = Math.min(lo + 2 * width, n);
478	      let i = lo;
479	      let j = mid;
