505	      const d = s.charCodeAt(i + 1);
506	      if (d >= 0xdc00 && d <= 0xdfff) {
507	        out.push((c - 0xd800) * 0x400 + (d - 0xdc00) + 0x10000);
508	        i += 2;
509	        continue;
510	      }
511	    }
512	    out.push(c);
513	    i += 1;
